Status SegmentImpl::internal_insert(Doc &doc) {
  uint64_t g_doc_id = doc_id_allocator_.fetch_add(1);
  doc.set_doc_id(g_doc_id);

  if (ready_for_dump_block()) {
    auto s = flush();
    CHECK_RETURN_STATUS(s);
  }

